/// <summary>
///     The <c>AVASRSPrintDestinationSettingsForm_Extension</c> class is the extension for <c>SRSPrintDestinationSettingsForm</c>
/// </summary>
[ExtensionOf(FormStr(SRSPrintDestinationSettingsForm))]
final class AVASRSPrintDestinationSettingsForm_Extension
{
    public SRSPrintDestinationSettings              clsSRSPrintDestinationSettings;
    public AVASalesOrderDelegationReportContract    clsAVASalesOrderDelegationReportContract;

}

Method.Source:
/// <summary>
///     AVA <c>init</c> method.
///     AVA - Schneider 03.05.2024
///     Initialize a new print destination settings form.
/// </summary>
public void init()
{
    FormControl locEmailBodyEditor;
    FormStringControl locFormStringControl;

    next init();

    clsSRSPrintDestinationSettings = this._printDestinationSettings;

    clsAVASalesOrderDelegationReportContract = clsSRSPrintDestinationSettings.parmAVASalesOrderDelegationReportContract();
    if(clsAVASalesOrderDelegationReportContract != null)
    {
        locFormStringControl = this.design().controlName(formControlStr(SRSPrintDestinationSettingsForm, AVAPCMEmailSetup)) as FormStringControl;
        locFormStringControl.allowEdit(false);
        locEmailBodyEditor = this.design().controlName(formControlStr(SRSPrintDestinationSettingsForm, EmailBodyEditor)) as FormControl;
        locEmailBodyEditor.allowEdit(false);
        //locEmailBodyEditor.visible(false);
    }
}

/// <summary>
///     AVA <c>avaFormatEmailContent</c> method.
///     AVA - Schneider 14.05.2024
/// </summary>
public void avaFormatEmailContent()
{
    SRSPrintDestinationSettings locSRSPrintDestinationSettings;
    SrsReportDataContract       locSrsReportDataContract;
    AVAPCMEmailFormatter        locAVAPCMEmailFormatter;

    AVAPCMEmailSetupId          locAVAPCMEmailSetupId;
    AVAPCMEmailSetup            locAVAPCMEmailSetup;


    locSRSPrintDestinationSettings  = clsSRSPrintDestinationSettings;

    //locAVAPCMEmailFormatter = AVAPCMEmailFormatter::construct(clsSRSPrintDestinationSettings);
    //locAVAPCMEmailFormatter.set .set .setContract( (clsSRSPrintDestinationSettings.parm _reportDataContract.parmRdpContract());


    if(clsSRSPrintDestinationSettings)
    {
        locAVAPCMEmailSetupId           = clsSRSPrintDestinationSettings.parmAVAPCMEmailSetupIdReplacement();
        locAVAPCMEmailSetup             = clsSRSPrintDestinationSettings.parmAVAPCMEmailSetupReplacement();
        locAVAPCMEmailFormatter         = clsSRSPrintDestinationSettings.parmAVAPCMEmailFormatter();
        if(     locAVAPCMEmailSetupId 
            &&  !locAVAPCMEmailSetup.RecId  )
        {
            locAVAPCMEmailSetup = AVAPCMEmailSetup::find(locAVAPCMEmailSetupId);
        }
    }
}
